query.sparql:

SELECT ?itemLabel WHERE {
  ?item wdt:P493 "E11".  # ICD-10 code
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ar,en". }
}


SELECT ?item ?itemLabel ?itemLabel_en ?itemLabel_ar WHERE {
  ?item rdfs:label "diabetes mellitus tipo 2"@pt.
  OPTIONAL { ?item rdfs:label ?itemLabel_en. FILTER(LANG(?itemLabel_en) = "en") }
  OPTIONAL { ?item rdfs:label ?itemLabel_ar. FILTER(LANG(?itemLabel_ar) = "ar") }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "pt". }
}


SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q12140.  # instance of medication
  ?item rdfs:label "metformin"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[LANG]". }
}

check.script:

// Pseudo-código para verificação
const ptKeys = extractKeys('messages/pt/*.json');
for (const locale of ['en', 'es', 'fr', 'ar', 'zh', 'el', 'hi', 'ru']) {
  const localeKeys = extractKeys(`messages/${locale}/*.json`);
  const missing = ptKeys.filter(k => !localeKeys.includes(k));
  if (missing.length > 0) {
    report(`${locale} missing: ${missing.join(', ')}`);
  }
}
